"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[68912],{45473:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"RockController","desc":"Renders Rock Hazards. On `RockSpawn` it takes a pooled copy of the rock model,\\nscales it, applies the biome look (eruption rocks: the biome\'s\\n`RockConfig.Eruptions` look and gravity), and moves + spins it every frame\\nwith `RockMath.positionAt` (the server\'s formula). On `EruptionStart` it plays\\nthe current biome\'s source effect (`PILLAR_TEMPLATE`: Volcano fire pillar, Ice\\nfall). On `RockRemoved` it plays the\\nVFX/SFX for the reason and returns the model to the pool. Shield hits are\\ndrawn by `TrainShieldDomeController` from `TrainShieldHit`, not here.","realm":["Client"],"source":{"line":15,"path":"src/StarterPlayer/StarterPlayerScripts/RockController.client.luau"}}')}}]);